create  view frinv174 as SELECT     dbo.HEAD_LST.NUMBER,dbo.JAMFACTPRS.mab - dbo.HEAD_LST.M_NAGHD - dbo.HEAD_LST.MABL_VAR - dbo.HEAD_LST.MABL_HAV + dbo.HEAD_LST.MABL_HAZ - ISNULL(dbo.jamchkfact.mabch,0) AS Expr1 FROM         dbo.HEAD_LST INNER JOIN dbo.JAMFACTPRS ON dbo.HEAD_LST.NUMBER = dbo.JAMFACTPRS.NUMBER AND dbo.HEAD_LST.TAG = dbo.JAMFACTPRS.TAG + 11 LEFT OUTER JOIN dbo.jamchkfact ON dbo.JAMFACTPRS.NUMBER = dbo.jamchkfact.NUMBER WHERE     (dbo.HEAD_LST.TAG = 12) AND (dbo.HEAD_LST.CUST_NO = N'213-1-1-666') GROUP BY dbo.HEAD_LST.NUMBER,dbo.JAMFACTPRS.mab - dbo.HEAD_LST.M_NAGHD - dbo.HEAD_LST.MABL_VAR - dbo.HEAD_LST.MABL_HAV + dbo.HEAD_LST.MABL_HAZ - ISNULL(dbo.jamchkfact.mabch,0) HAVING      (dbo.JAMFACTPRS.mab - dbo.HEAD_LST.M_NAGHD - dbo.HEAD_LST.MABL_VAR - dbo.HEAD_LST.MABL_HAV + dbo.HEAD_LST.MABL_HAZ - ISNULL(dbo.jamchkfact.mabch,0) <> 0)
